        await session.AuthenticateAsync(GetDefaultManagementKey(state.FirmwareVersion));

        // Step 1: Generate RSA 2048 key
        var rsaPublicKey = await session.GenerateKeyAsync(
            Slot.Authentication,
            KeyType.Rsa2048);

        Assert.NotNull(rsaPublicKey);
        Assert.IsType<RSAPublicKey>(rsaPublicKey);

        // Verify metadata shows RSA 2048
        var metadataRsa = await session.GetSlotMetadataAsync(Slot.Authentication);
        Assert.NotNull(metadataRsa);
        Assert.Equal(KeyType.Rsa2048, metadataRsa.Value.KeyType);

        // Step 2: Overwrite with ECC P-256
        var eccPublicKey = await session.GenerateKeyAsync(
            Slot.Authentication,
            KeyType.P256);

        Assert.NotNull(eccPublicKey);
        Assert.IsType<ECPublicKey>(eccPublicKey);

        // Verify metadata now shows ECC P-256
        var metadataEcc = await session.GetSlotMetadataAsync(Slot.Authentication);
        Assert.NotNull(metadataEcc);
        Assert.Equal(KeyType.P256, metadataEcc.Value.KeyType);

        // Verify the ECC key is functional
        await session.VerifyPinAsync(DefaultPin);
        var hash = SHA256.HashData("overwrite test"u8);
        var signature = await session.SignOrDecryptAsync(
            Slot.Authentication,
            KeyType.P256,
            hash);

        Assert.False(signature.IsEmpty);

        using var ecdsa = ECDsa.Create();
        ecdsa.ImportSubjectPublicKeyInfo(((ECPublicKey)eccPublicKey).ExportSubjectPublicKeyInfo(), out _);
        Assert.True(ecdsa.VerifyHash(hash, signature.Span, DSASignatureFormat.Rfc3279DerSequence));
    }

{
        await using var session = await state.Device.CreatePivSessionAsync();
        await session.ResetAsync();
        await session.AuthenticateAsync(GetDefaultManagementKey(state.FirmwareVersion));

        // Step 1: Generate ECC P-256 key
        var eccPublicKey = await session.GenerateKeyAsync(
            Slot.Authentication,
            KeyType.P256);

        Assert.NotNull(eccPublicKey);
        Assert.IsType<ECPublicKey>(eccPublicKey);

        // Verify metadata shows ECC P-256
        var metadataEcc = await session.GetSlotMetadataAsync(Slot.Authentication);
        Assert.NotNull(metadataEcc);
        Assert.Equal(KeyType.P256, metadataEcc.Value.KeyType);

        // Step 2: Overwrite with RSA 2048
        var rsaPublicKey = await session.GenerateKeyAsync(
            Slot.Authentication,
            KeyType.Rsa2048);

        Assert.NotNull(rsaPublicKey);
        Assert.IsType<RSAPublicKey>(rsaPublicKey);

        // Verify metadata now shows RSA 2048
        var metadataRsa = await session.GetSlotMetadataAsync(Slot.Authentication);
        Assert.NotNull(metadataRsa);
        Assert.Equal(KeyType.Rsa2048, metadataRsa.Value.KeyType);

        // Verify the RSA key is functional
        await session.VerifyPinAsync(DefaultPin);

        // SHA-256 DigestInfo prefix
        byte[] sha256DigestInfo =
        [
            0x30, 0x31, 0x30, 0x0D, 0x06, 0x09, 0x60, 0x86,
            0x48, 0x01, 0x65, 0x03, 0x04, 0x02, 0x01, 0x05,
            0x00, 0x04, 0x20
        ];

        var dataToSign = "overwrite RSA test"u8.ToArray();
        var hash = SHA256.HashData(dataToSign);

        // Build PKCS#1 v1.5 padding
        var padded = new byte[CryptographicDefinitions.Keys.Rsa2048.KeySizeBytes];
        padded[0] = 0x00;
        padded[1] = 0x01;
        var paddingLength = padded.Length - 3 - sha256DigestInfo.Length - hash.Length;
        for (var i = 2; i < 2 + paddingLength; i++)
        {
            padded[i] = 0xFF;
        }
        padded[2 + paddingLength] = 0x00;
        Array.Copy(sha256DigestInfo, 0, padded, 3 + paddingLength, sha256DigestInfo.Length);
        Array.Copy(hash, 0, padded, 3 + paddingLength + sha256DigestInfo.Length, hash.Length);

        var signature = await session.SignOrDecryptAsync(
            Slot.Authentication,
            KeyType.Rsa2048,
            padded);

        Assert.Equal(CryptographicDefinitions.Keys.Rsa2048.KeySizeBytes, signature.Length);

        using var rsa = RSA.Create();
        rsa.ImportSubjectPublicKeyInfo(((RSAPublicKey)rsaPublicKey).ExportSubjectPublicKeyInfo(), out _);
        Assert.True(rsa.VerifyData(dataToSign, signature.Span, HashAlgorithmName.SHA256, RSASignaturePadding.Pkcs1));
    }

{
        await using var session = await state.Device.CreatePivSessionAsync(
            new SessionCreationOptions { PreferredConnectionType = ConnectionType.SmartCard });

        ManagementKeyMetadata managementKey = await session.GetManagementKeyMetadataAsync();
        PinMetadata pin = await session.GetPinMetadataAsync();
        SlotMetadata? retired20 = await session.GetSlotMetadataAsync(Slot.Retired20);

        output.WriteLine($"Firmware={state.FirmwareVersion}");
        output.WriteLine(
            $"ManagementKey: IsDefault={managementKey.IsDefault}, KeyType={managementKey.KeyType}, " +
            $"TouchPolicy={managementKey.TouchPolicy}");
        output.WriteLine(
            $"PIN: IsDefault={pin.IsDefault}, TotalRetries={pin.TotalRetries}, " +
            $"RetriesRemaining={pin.RetriesRemaining}");
        output.WriteLine($"Retired20: Occupied={retired20 is not null}");
    }

{
        var prompt = new RecordingUserPresencePrompt(output);
        await using var session = await state.Device.CreatePivSessionAsync(
            new SessionCreationOptions
            {
                PreferredConnectionType = ConnectionType.SmartCard,
                UserPresencePrompt = prompt
            });

        ManagementKeyMetadata managementKeyMetadata = await session.GetManagementKeyMetadataAsync();
        SlotMetadata? existingSlotMetadata = await session.GetSlotMetadataAsync(Slot.Retired20);

        output.WriteLine(
            $"Prerequisites: Firmware={state.FirmwareVersion}, ManagementKeyIsDefault={managementKeyMetadata.IsDefault}, " +
            $"ManagementKeyType={managementKeyMetadata.KeyType}, " +
            $"ManagementKeyTouchPolicy={managementKeyMetadata.TouchPolicy}, " +
            $"Retired20Occupied={existingSlotMetadata is not null}");

        Skip.If(
            !managementKeyMetadata.IsDefault,
            "The PIV management key is not the known default; refusing to authenticate or mutate the applet.");
        Skip.If(
            managementKeyMetadata.TouchPolicy is not TouchPolicy.Default and not TouchPolicy.Never,
            $"The management key touch policy is {managementKeyMetadata.TouchPolicy}; refusing an unrelated touch " +
            "during prerequisite authentication.");
        Skip.If(
            managementKeyMetadata.KeyType is not KeyType.TripleDes and not KeyType.Aes192,
            $"The default management key cannot be used with reported key type {managementKeyMetadata.KeyType}.");
        Skip.If(
            session.ManagementKeyType != managementKeyMetadata.KeyType,
            $"The session key type {session.ManagementKeyType} does not match metadata " +
            $"{managementKeyMetadata.KeyType}; refusing authentication.");
        Skip.If(
            existingSlotMetadata is not null,
            "PIV slot Retired20 is occupied; refusing to overwrite it. Clear it deliberately before running this probe.");

        byte[] managementKey = PivSession.DefaultManagementKey.ToArray();
        try
        {
            await session.AuthenticateAsync(managementKey);
        }
        finally
        {
            CryptographicOperations.ZeroMemory(managementKey);
        }

        Assert.Empty(prompt.Requested);
        Assert.Empty(prompt.Resolved);

        var keyCreated = false;
        byte[] digest = SHA256.HashData("PIV user-presence probe"u8);
        Memory<byte> signature = default;
        try
        {
            IPublicKey generatedPublicKey = await session.GenerateKeyAsync(
                Slot.Retired20,
                KeyType.P256,
                new KeyCreationOptions
                {
                    PinPolicy = PinPolicy.Never,
                    TouchPolicy = TouchPolicy.Always
                });
            keyCreated = true;
            ECPublicKey publicKey = Assert.IsType<ECPublicKey>(generatedPublicKey);

            Assert.Empty(prompt.Requested);
            Assert.Empty(prompt.Resolved);
            output.WriteLine(
                "The signing operation uses a 30-second cooperative cancellation token. It does not guarantee " +
                "interruption of an in-flight SmartCard exchange.");

            using var operationCts = new CancellationTokenSource(TimeSpan.FromSeconds(30));
            signature = await session.SignOrDecryptAsync(
                Slot.Retired20,
                KeyType.P256,
                digest,
                operationCts.Token);

            using ECDsa verifier = ECDsa.Create(publicKey.Parameters);
            Assert.True(verifier.VerifyHash(
                digest,
                signature.Span,
                DSASignatureFormat.Rfc3279DerSequence));

            UserPresenceContext requested = Assert.Single(prompt.Requested);
            Assert.Equal(UserPresenceBasis.PolicyRequires, requested.Basis);
            Assert.Equal("PIV", requested.Application);
            Assert.Equal(Slot.Retired20.ToString(), requested.Scope);

            (UserPresenceContext Context, UserPresenceOutcome Outcome, CancellationToken CancellationToken) resolved =
                Assert.Single(prompt.Resolved);
            Assert.Same(requested, resolved.Context);
            Assert.Equal(UserPresenceOutcome.Completed, resolved.Outcome);
            Assert.Equal(CancellationToken.None, resolved.CancellationToken);

            using var followUpCts = new CancellationTokenSource(TimeSpan.FromSeconds(30));
            SlotMetadata? slotMetadata = await session.GetSlotMetadataAsync(
                Slot.Retired20,
                followUpCts.Token);
            Assert.NotNull(slotMetadata);
            Assert.Equal(KeyType.P256, slotMetadata.Value.KeyType);
            Assert.Equal(PinPolicy.Never, slotMetadata.Value.PinPolicy);
            Assert.Equal(TouchPolicy.Always, slotMetadata.Value.TouchPolicy);
            Assert.Equal(state.SerialNumber, await session.GetSerialNumberAsync(followUpCts.Token));
        }
        finally
        {
            CryptographicOperations.ZeroMemory(digest);
            if (!signature.IsEmpty)
            {
                CryptographicOperations.ZeroMemory(signature.Span);
            }

            if (keyCreated)
            {
                await session.DeleteKeyAsync(Slot.Retired20);
                Assert.Null(await session.GetSlotMetadataAsync(Slot.Retired20));
                output.WriteLine("Cleanup: deleted the test-created key from PIV slot Retired20.");
            }
        }
    }
